mapper.select:
SELECT w.tenant_id AS workspaceId, COUNT(*) AS total
FROM workitem w
WHERE w.tenant_id IN
#{workspaceId}
  AND w.is_deleted = 0
  AND w.gmt_create >= #{start}
  AND w.gmt_create < #{end}

  AND w.work_type IN
  #{workType}

GROUP BY w.tenant_id

SELECT counted.tenant_id AS workspaceId, COUNT(*) AS total FROM ( SELECT w.tenant_id AS tenant_id, (SELECT MAX(e.gmt_create) FROM workitem_event e JOIN status_node done_node ON done_node.tenant_id = e.tenant_id AND done_node.code = e.to_val AND done_node.category = 'DONE' WHERE e.tenant_id = w.tenant_id AND e.workitem_id = w.id AND e.event_type = 'STATUS_CHANGE' AND done_node.template_id = w.template_id) AS done_at FROM workitem w JOIN status_node sn ON sn.id = w.status_node_id AND sn.tenant_id = w.tenant_id WHERE w.tenant_id IN #{workspaceId} AND w.is_deleted = 0 AND sn.category = 'DONE'
AND w.work_type IN #{workType}
) counted WHERE counted.done_at >= #{start} AND counted.done_at < #{end} GROUP BY counted.tenant_id

SELECT w.tenant_id AS workspaceId, COUNT(*) AS total
FROM workitem w
JOIN status_node sn ON sn.id = w.status_node_id AND sn.tenant_id = w.tenant_id
WHERE w.tenant_id IN
#{workspaceId}
  AND w.is_deleted = 0
  AND w.gmt_create >= #{start}
  AND w.gmt_create < #{end}
  AND sn.category IN ('INIT', 'IN_PROGRESS')

  AND w.work_type IN
  #{workType}

GROUP BY w.tenant_id

SELECT combined.tenant_id AS workspaceId, SUM(combined.credits) AS credits
FROM (
    SELECT tenant_id, COALESCE(credits, 0) AS credits
    FROM dispatch_ai_usage
    WHERE tenant_id IN
    #{workspaceId}
      AND usage_at >= #{start}
      AND usage_at < #{end}
    UNION ALL
    SELECT tenant_id, COALESCE(credits, 0) AS credits
    FROM agent_conversation_usage
    WHERE tenant_id IN
    #{workspaceId}
      AND usage_at >= #{start}
      AND usage_at < #{end}
) combined
GROUP BY combined.tenant_id
